//! The crate-host value encoding, interpreter side (the host side is generated by `gen.rs` from the same table).
//!
//! Self-describing, little-endian: one tag byte, then the payload. Both sides check the tag against the declared
//! [`WireTy`], so a host that sends a different shape than the surface declares is an error, never a misread.
//!
//! | tag | value | payload |
//! |---|---|---|
//! | 0 | unit | - |
//! | 1 | integer | i128 (16 bytes) |
//! | 2 | float | f64 bits (8 bytes; `f32` widened exactly) |
//! | 3 | bool | 1 byte |
//! | 4 | char | u32 |
//! | 5 | string | u32 length, UTF-8 bytes |
//! | 6 | Vec | u32 count, items |
//! | 7 / 8 | None / Some | - / item |
//! | 9 / 10 | Ok / Err | item |
//! | 11 | tuple | u32 count, items |
//! | 12 | handle (opaque crate value) | u64 id in the host's table |

use super::super::int::IntTy;
use super::super::place::deref_value;
use super::super::value::{FloatTy, Payload, Value};
use super::sig::WireTy;

pub const UNIT: u8 = 0;
pub const INT: u8 = 1;
pub const FLOAT: u8 = 2;
pub const BOOL: u8 = 3;
pub const CHAR: u8 = 4;
pub const STR: u8 = 5;
pub const VEC: u8 = 6;
pub const NONE: u8 = 7;
pub const SOME: u8 = 8;
pub const OK: u8 = 9;
pub const ERR: u8 = 10;
pub const TUPLE: u8 = 11;
pub const HANDLE: u8 = 12;

fn len32(out: &mut Vec<u8>, n: usize) -> Result<(), String> {
    let n = u32::try_from(n).map_err(|_| "a value larger than 4 GiB cannot cross to the crate host".to_string())?;
    out.extend_from_slice(&n.to_le_bytes());
    Ok(())
}

/// Append `v`, which the surface declares as `t`.
pub fn encode(v: &Value, t: &WireTy, out: &mut Vec<u8>) -> Result<(), String> {
    let v = match v {
        Value::Ref(_) | Value::Rc(_) => deref_value(v.clone()).map_err(|_| "a reference that cannot be read".to_string())?,
        _ => v.clone(),
    };
    let bad = || format!("expected {}, found {}", show(t), v.type_name());
    match (t, &v) {
        (WireTy::Unit, Value::Unit) => out.push(UNIT),
        (WireTy::Int(_), Value::Int(n, _)) => {
            out.push(INT);
            out.extend_from_slice(&n.to_le_bytes());
        }
        (WireTy::Float(_), Value::Float(x, _)) => {
            out.push(FLOAT);
            out.extend_from_slice(&x.to_bits().to_le_bytes());
        }
        (WireTy::Bool, Value::Bool(b)) => {
            out.push(BOOL);
            out.push(*b as u8);
        }
        (WireTy::Char, Value::Char(c)) => {
            out.push(CHAR);
            out.extend_from_slice(&(*c as u32).to_le_bytes());
        }
        (WireTy::Str, Value::Str(s)) => {
            out.push(STR);
            len32(out, s.len())?;
            out.extend_from_slice(s.as_bytes());
        }
        (WireTy::Vec(e), Value::Vec(_)) => {
            let items = v.items();
            out.push(VEC);
            len32(out, items.len())?;
            for x in items {
                encode(x, e, out)?;
            }
        }
        (WireTy::Tuple(ts), Value::Tuple(items)) if ts.len() == items.len() => {
            out.push(TUPLE);
            len32(out, ts.len())?;
            for (x, t) in items.iter().zip(ts) {
                encode(x, t, out)?;
            }
        }
        (WireTy::Option(e), Value::Enum(_)) => match v.as_option() {
            Some(None) => out.push(NONE),
            Some(Some(x)) => {
                out.push(SOME);
                encode(x, e, out)?;
            }
            None => return Err(bad()),
        },
        (WireTy::Handle(q), Value::Native(_)) => match super::handle::parts(&v) {
            Some((hq, id)) if hq == q => {
                out.push(HANDLE);
                out.extend_from_slice(&id.to_le_bytes());
            }
            _ => return Err(bad()),
        },
        (WireTy::Result(a, b), Value::Enum(ev)) if &*ev.ty == "Result" => {
            let Payload::Tuple(p) = &ev.payload else { return Err(bad()) };
            let x = p.first().ok_or_else(bad)?;
            if ev.idx == 0 {
                out.push(OK);
                encode(x, a, out)?;
            } else {
                out.push(ERR);
                encode(x, b, out)?;
            }
        }
        _ => return Err(bad()),
    }
    Ok(())
}

fn take<'a>(inp: &mut &'a [u8], n: usize) -> Result<&'a [u8], String> {
    if inp.len() < n {
        return Err("the crate host sent a truncated value".into());
    }
    let (a, b) = inp.split_at(n);
    *inp = b;
    Ok(a)
}

fn u32_at(inp: &mut &[u8]) -> Result<u32, String> {
    Ok(u32::from_le_bytes(take(inp, 4)?.try_into().unwrap()))
}

/// Makes the value of a handle the host returned: `(crate::Type, id)`.
pub type MakeHandle<'a> = &'a dyn Fn(&str, u64) -> Value;

/// Read one value the surface declares as `t` (handles become handles with no host behind them).
pub fn decode(inp: &mut &[u8], t: &WireTy) -> Result<Value, String> {
    decode_with(inp, t, &|q, id| super::handle::value(q, "handle", id, None))
}

/// Read one value; `mk` turns a host handle into a program value.
pub fn decode_with(inp: &mut &[u8], t: &WireTy, mk: MakeHandle<'_>) -> Result<Value, String> {
    let decode = |inp: &mut &[u8], t: &WireTy| decode_with(inp, t, mk);
    let tag = take(inp, 1)?[0];
    let bad = || format!("the crate host sent tag {tag} where the surface declares {}", show(t));
    Ok(match (t, tag) {
        (WireTy::Unit, UNIT) => Value::Unit,
        (WireTy::Int(name), INT) => {
            let n = i128::from_le_bytes(take(inp, 16)?.try_into().unwrap());
            Value::Int(n, IntTy::from_name(name).unwrap_or(IntTy::I64))
        }
        (WireTy::Float(name), FLOAT) => {
            let x = f64::from_bits(u64::from_le_bytes(take(inp, 8)?.try_into().unwrap()));
            Value::Float(x, if *name == "f32" { FloatTy::F32 } else { FloatTy::F64 })
        }
        (WireTy::Bool, BOOL) => Value::Bool(take(inp, 1)?[0] != 0),
        (WireTy::Char, CHAR) => {
            let c = u32_at(inp)?;
            Value::Char(char::from_u32(c).ok_or_else(|| format!("the crate host sent an invalid char {c:#x}"))?)
        }
        (WireTy::Str, STR) => {
            let n = u32_at(inp)? as usize;
            let b = take(inp, n)?;
            Value::str(std::str::from_utf8(b).map_err(|_| "the crate host sent a string that is not UTF-8".to_string())?)
        }
        (WireTy::Vec(e), VEC) => {
            let n = u32_at(inp)? as usize;
            let mut items = Vec::with_capacity(n.min(1 << 16));
            for _ in 0..n {
                items.push(decode(inp, e)?);
            }
            Value::vec(items)
        }
        (WireTy::Tuple(ts), TUPLE) => {
            let n = u32_at(inp)? as usize;
            if n != ts.len() {
                return Err(bad());
            }
            let items = ts.iter().map(|t| decode(inp, t)).collect::<Result<Vec<_>, _>>()?;
            Value::tuple(items)
        }
        (WireTy::Option(_), NONE) => Value::none(),
        (WireTy::Option(e), SOME) => Value::some(decode(inp, e)?),
        (WireTy::Result(a, _), OK) => Value::ok(decode(inp, a)?),
        (WireTy::Result(_, b), ERR) => Value::err(decode(inp, b)?),
        (WireTy::Handle(q), HANDLE) => {
            let id = u64::from_le_bytes(take(inp, 8)?.try_into().unwrap());
            mk(q, id)
        }
        _ => return Err(bad()),
    })
}

/// The surface spelling of a wire type (for messages).
pub fn show(t: &WireTy) -> String {
    match t {
        WireTy::Unit => "()".into(),
        WireTy::Int(n) | WireTy::Float(n) => n.to_string(),
        WireTy::Bool => "bool".into(),
        WireTy::Char => "char".into(),
        WireTy::Str => "string".into(),
        WireTy::Vec(e) => format!("Vec<{}>", show(e)),
        WireTy::Option(e) => format!("Option<{}>", show(e)),
        WireTy::Result(a, b) => format!("Result<{}, {}>", show(a), show(b)),
        WireTy::Tuple(ts) => format!("({})", ts.iter().map(show).collect::<Vec<_>>().join(", ")),
        WireTy::Handle(q) => q.rsplit("::").next().unwrap_or(q).to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn round(v: Value, t: WireTy) -> Value {
        let mut b = Vec::new();
        encode(&v, &t, &mut b).unwrap();
        let mut s = &b[..];
        let back = decode(&mut s, &t).unwrap();
        assert!(s.is_empty(), "trailing bytes");
        back
    }

    #[test]
    fn bytes_are_the_documented_layout() {
        // the host side is generated Rust; these bytes are what it must produce and accept
        let mut b = Vec::new();
        encode(&Value::str("hé"), &WireTy::Str, &mut b).unwrap();
        assert_eq!(b, [5, 3, 0, 0, 0, b'h', 0xc3, 0xa9]);
        let mut b = Vec::new();
        encode(&Value::Int(-2, IntTy::I64), &WireTy::Int("i64"), &mut b).unwrap();
        assert_eq!(b[0], 1);
        assert_eq!(&b[1..], &(-2i128).to_le_bytes());
        let mut b = Vec::new();
        encode(&Value::some(Value::vec(vec![Value::Bool(true)])), &WireTy::Option(Box::new(WireTy::Vec(Box::new(WireTy::Bool)))), &mut b).unwrap();
        assert_eq!(b, [8, 6, 1, 0, 0, 0, 3, 1]);
    }

    #[test]
    fn values_round_trip_with_their_declared_widths() {
        let t = WireTy::Result(Box::new(WireTy::Tuple(vec![WireTy::Int("usize"), WireTy::Float("f32"), WireTy::Char])), Box::new(WireTy::Str));
        let v = Value::ok(Value::tuple(vec![Value::Int(7, IntTy::Lit), Value::Float(0.5, FloatTy::Lit), Value::Char('λ')]));
        let back = round(v, t);
        let inner = match &back {
            Value::Enum(e) => match &e.payload {
                Payload::Tuple(p) => p[0].clone(),
                _ => panic!(),
            },
            _ => panic!(),
        };
        let items = inner.items().to_vec();
        assert!(matches!(items[0], Value::Int(7, IntTy::Usize)));
        assert!(matches!(items[1], Value::Float(x, FloatTy::F32) if x == 0.5));
        assert!(matches!(items[2], Value::Char('λ')));
        let e = round(Value::err(Value::str("bad")), WireTy::Result(Box::new(WireTy::Unit), Box::new(WireTy::Str)));
        assert!(matches!(&e, Value::Enum(ev) if ev.idx == 1));
        assert!(matches!(round(Value::none(), WireTy::Option(Box::new(WireTy::Int("u8")))).as_option(), Some(None)));
    }

    #[test]
    fn handles_cross_as_ids_and_keep_their_type() {
        let t = WireTy::Option(Box::new(WireTy::Handle("ctr::Counter".into())));
        let mut b = Vec::new();
        encode(&Value::some(super::super::handle::value("ctr::Counter", "Counter", 9, None)), &t, &mut b).unwrap();
        assert_eq!(b, [8, 12, 9, 0, 0, 0, 0, 0, 0, 0]);
        let back = decode(&mut &b[..], &t).unwrap();
        assert_eq!(super::super::handle::parts(back.as_option().unwrap().unwrap()), Some(("ctr::Counter", 9)));
        let other = super::super::handle::value("ctr::Other", "Other", 1, None);
        assert!(encode(&other, &WireTy::Handle("ctr::Counter".into()), &mut Vec::new()).is_err());
    }

    #[test]
    fn a_shape_the_surface_does_not_declare_is_an_error() {
        let mut b = Vec::new();
        assert!(encode(&Value::str("x"), &WireTy::Int("i64"), &mut b).unwrap_err().contains("expected i64, found String"));
        let mut s: &[u8] = &[5, 1, 0, 0, 0, b'x'];
        assert!(decode(&mut s, &WireTy::Int("u32")).unwrap_err().contains("tag 5 where the surface declares u32"));
        let mut s: &[u8] = &[5, 9, 0, 0, 0, b'x'];
        assert!(decode(&mut s, &WireTy::Str).unwrap_err().contains("truncated"));
    }
}
